import{_ as o,r as n,o as d,c as r,e as a,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Поле Data Table - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Data Table"},"headers":[{"level":4,"title":"Конфигурация столбцов","slug":"конфигурация-столбцов","link":"#конфигурация-столбцов","children":[]},{"level":4,"title":"Валидация столбцов","slug":"валидация-столбцов","link":"#валидация-столбцов","children":[]},{"level":4,"title":"AJAX-обработчики","slug":"ajax-обработчики","link":"#ajax-обработчики","children":[]}],"relativePath":"3.x/ru/element/form/widget-datatable.md","filePath":"3.x/ru/element/form/widget-datatable.md"}'),p={name:"3.x/ru/element/form/widget-datatable.md"};function i(u,t,g,k,m,h){const e=n("pre-heading"),s=n("post-heading");return d(),r("div",null,[a(e),t[0]||(t[0]=c("h1",null,"Поле Data Table",-1)),a(s),t[1]||(t[1]=l(`<p><code>datatable</code> — рендерит редактируемую таблицу записей, отформатированную в виде сетки. Содержимое ячеек может редактироваться прямо в сетке, что позволяет управлять несколькими строками и столбцами информации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">data</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datatable
    <span class="token key atrule">adding</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">deleting</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">columns</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">searching</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>Для использования с моделью поле должно быть определено в <a href="./../../extend/system/models.html">свойстве jsonable</a> или в любом другом свойстве, поддерживающем хранение в виде массива.</p></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию (строка), необязательно.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>adding</strong></td><td>разрешает добавление записей в таблицу данных. По умолчанию: <code>true</code>.</td></tr><tr><td><strong>btnAddRowLabel</strong></td><td>определяет пользовательскую метку для кнопки «Add Row Above».</td></tr><tr><td><strong>btnAddRowBelowLabel</strong></td><td>определяет пользовательскую метку для кнопки «Add Row Below».</td></tr><tr><td><strong>btnDeleteRowLabel</strong></td><td>определяет пользовательскую метку для кнопки «Delete Row».</td></tr><tr><td><strong>columns</strong></td><td>массив, представляющий конфигурацию столбцов таблицы данных. См. раздел <em>Конфигурация столбцов</em> ниже.</td></tr><tr><td><strong>deleting</strong></td><td>разрешает удаление записей из таблицы данных. По умолчанию: <code>true</code>.</td></tr><tr><td><strong>dynamicHeight</strong></td><td>если <code>true</code>, высота таблицы данных будет увеличиваться или уменьшаться в зависимости от добавленных записей, до максимального размера, определённого значением конфигурации <code>height</code>. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>fieldName</strong></td><td>определяет пользовательское имя поля для использования в POST-данных, отправляемых из таблицы данных. Оставьте пустым для использования псевдонима поля по умолчанию.</td></tr><tr><td><strong>height</strong></td><td>высота таблицы данных в пикселях. Если установлено <code>false</code>, таблица данных растянется для заполнения контейнера поля.</td></tr><tr><td><strong>keyFrom</strong></td><td>атрибут данных, используемый как ключ каждой записи. Обычно должен быть установлен в <code>id</code>. Поддерживает только целочисленные значения.</td></tr><tr><td><strong>postbackHandlerName</strong></td><td>указывает имя AJAX-обработчика, с которым будет отправлено содержимое таблицы данных. При значении <code>null</code> (по умолчанию) имя обработчика будет автоматически определено из имени запроса, используемого формой, содержащей таблицу данных. Рекомендуется оставлять значение <code>null</code>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>количество записей на странице. Если установлено <code>false</code>, пагинация будет отключена.</td></tr><tr><td><strong>searching</strong></td><td>разрешает поиск записей через поле поиска. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>toolbar</strong></td><td>массив, представляющий конфигурацию панели инструментов таблицы данных.</td></tr></tbody></table></div><h4 id="конфигурация-столбцов"><a href="#конфигурация-столбцов" class="header-anchor">#</a> Конфигурация столбцов</h4><p>Виджет таблицы данных позволяет задавать столбцы в виде массива через переменную конфигурации <code>columns</code>. Каждый столбец должен использовать имя поля в качестве ключа и следующие переменные конфигурации для настройки поля.</p><p>Пример:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">id</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> ID
        <span class="token key atrule">validation</span><span class="token punctuation">:</span>
            <span class="token key atrule">integer</span><span class="token punctuation">:</span>
                <span class="token key atrule">message</span><span class="token punctuation">:</span> Please enter a number
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Name
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Опция</th><th>Описание</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>тип ввода для ячеек этого столбца. Должен быть одним из: <code>string</code>, <code>checkbox</code>, <code>dropdown</code> или <code>autocomplete</code>.</td></tr><tr><td><strong>options</strong></td><td>используется только для столбцов <code>dropdown</code> и <code>autocomplete</code>. Ключ массива определяет значение опции, значение массива определяет метку опции. См. раздел AJAX-обработчики ниже.</td></tr><tr><td><strong>readOnly</strong></td><td>является ли столбец доступным только для чтения. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>title</strong></td><td>определяет заголовок столбца.</td></tr><tr><td><strong>validation</strong></td><td>массив, определяющий валидацию содержимого ячеек столбца. См. раздел <em>Валидация столбцов</em> ниже.</td></tr><tr><td><strong>width</strong></td><td>определяет ширину столбца в пикселях.</td></tr></tbody></table></div><h4 id="валидация-столбцов"><a href="#валидация-столбцов" class="header-anchor">#</a> Валидация столбцов</h4><p>Ячейки столбцов могут быть валидированы по следующим типам валидации. Валидация должна быть указана как массив, где тип валидации используется как ключ, а необязательное сообщение указывается как атрибут <code>message</code> для этой валидации.</p><div class="table"><table tabindex="0"><thead><tr><th>Валидация</th><th>Описание</th></tr></thead><tbody><tr><td><strong>float</strong></td><td>Проверяет, что данные являются числом с плавающей точкой. Может быть указан необязательный булевый атрибут <code>allowNegative</code>, разрешающий отрицательные числа с плавающей точкой.</td></tr><tr><td><strong>integer</strong></td><td>Проверяет, что данные являются целым числом. Может быть указан необязательный булевый атрибут <code>allowNegative</code>, разрешающий отрицательные целые числа.</td></tr><tr><td><strong>length</strong></td><td>Проверяет, что данные имеют определённую длину. Должны быть указаны целочисленные атрибуты <code>min</code> и <code>max</code>, представляющие минимальное и максимальное количество символов.</td></tr><tr><td><strong>regex</strong></td><td>Проверяет данные по регулярному выражению. Должен быть указан строковый атрибут <code>pattern</code>, определяющий регулярное выражение для проверки данных.</td></tr><tr><td><strong>required</strong></td><td>Проверяет, что данные должны быть введены перед сохранением.</td></tr></tbody></table></div><h4 id="ajax-обработчики"><a href="#ajax-обработчики" class="header-anchor">#</a> AJAX-обработчики</h4><p>Для столбцов типа <code>dropdown</code> или <code>autocomplete</code> список доступных опций может быть предоставлен через AJAX-обработчик, определённый в модели.</p><p>Обработчик должен следовать соглашению об именовании <code>getFieldNameDataTableOptions()</code>, где <code>FieldName</code> соответствует имени поля, определённому в конфигурации формы.</p><p>Метод должен возвращать ассоциативный массив, где ключ массива используется как сохраняемое значение, а значение массива — как отображаемая метка в таблице данных.</p><p>Например, для поля с именем <strong>country</strong> используется метод <code>getCountryDataTableOptions</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryDataTableOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Country</span><span class="token operator">::</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Это автоматически заполнит опции для поля <code>country</code> в DataTable.</p>`,20))])}const f=o(p,[["render",i]]);export{y as __pageData,f as default};
